<?= $this->extend('cms/layout') ?>
<?= $this->section('content') ?>
<?php $edit = $mode === 'edit'; $v = static fn($key, $default='') => old($key, $item[$key] ?? $default); ?>
<section class="cms-head"><div><small>CMS / LEGAL CONTENT</small><h1><?= $edit ? 'Edit update.' : 'New update.' ?></h1><p>Keep public legal content structured and publication-ready.</p></div></section>
<?php if ($msg = session()->getFlashdata('error')): ?><div class="error"><?= esc($msg) ?></div><?php endif; ?>
<form method="post" action="<?= $edit ? site_url('admin/cms/updates/save/'.$item['id']) : site_url('admin/cms/updates/store') ?>"><div class="form-grid"><section class="panel"><div class="field"><label>TITLE</label><input name="title" value="<?= esc($v('title')) ?>" required maxlength="180"></div><div class="field"><label>SLUG</label><input name="slug" value="<?= esc($v('slug')) ?>" maxlength="190" placeholder="auto-generated if left blank"></div><div class="field"><label>EXCERPT</label><textarea name="excerpt" style="min-height:100px"><?= esc($v('excerpt')) ?></textarea></div><div class="field"><label>CONTENT</label><textarea name="content" required><?= esc($v('content')) ?></textarea></div></section><section class="panel"><div class="field"><label>CATEGORY</label><select name="category"><option>Article</option><option <?= $v('category')==='Act'?'selected':'' ?>>Act</option><option <?= $v('category')==='Bill'?'selected':'' ?>>Bill</option><option <?= $v('category')==='BNS'?'selected':'' ?>>BNS</option><option <?= $v('category')==='Legal Update'?'selected':'' ?>>Legal Update</option></select></div><div class="field"><label>STATUS</label><select name="status"><option value="draft" <?= $v('status','draft')==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $v('status')==='published'?'selected':'' ?>>Published</option></select></div><div class="field"><label>PUBLISHED AT</label><input type="datetime-local" name="published_at" value="<?= $v('published_at') ? date('Y-m-d\TH:i', strtotime($v('published_at'))) : '' ?>"></div><div class="form-actions"><button class="btn btn-primary" type="submit"><?= $edit ? 'SAVE UPDATE' : 'CREATE UPDATE' ?></button><a class="btn" href="<?= site_url('admin/cms/updates') ?>">CANCEL</a></div></section></div></form>
<?= $this->endSection() ?>
